import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';import {test} from 'node:test';
class Param{value=0;setValueAtTime(v){this.value=v;}setTargetAtTime(v){this.value=v;}cancelScheduledValues(){}}
class Node{gain=new Param();frequency=new Param();playbackRate=new Param();connect(){return this;}start(){}stop(){}setPeriodicWave(){}}
class AudioContext{currentTime=0;sampleRate=48000;destination={};resume(){return Promise.resolve();}createPeriodicWave(){return{};}createBuffer(ch,size,rate){const data=new Float32Array(size);return{getChannelData:()=>data,duration:size/rate};}createBufferSource(){return new Node();}}
for(const file of ['jsnes-lite.readable.js','closure.min.js'])test('all eight keyboard buttons reach $4016 after compile: '+file,async()=>{const listeners={},nodes={rom:{files:[]},screen:{getContext:()=>({getImageData:()=>({data:new Uint8ClampedArray(256*240*4)}),putImageData(){}})},mute:{},full:{},status:{}};const document={open(){},write(){},close(){},querySelector:()=>({}),getElementById:id=>nodes[id],addEventListener(){}};const c=vm.createContext({document,console,performance,setTimeout:()=>1,clearTimeout(){},AudioContext,GainNode:Node,OscillatorNode:Node});c.window=c;c.addEventListener=(name,fn)=>(listeners[name]??=[]).push(fn);vm.runInContext(fs.readFileSync(new URL('../'+file,import.meta.url),'utf8'),c);const rom=fs.readFileSync(new URL('expected.nes',import.meta.url));nodes.rom.files=[{name:'test.nes',arrayBuffer:async()=>rom.buffer.slice(rom.byteOffset,rom.byteOffset+rom.length)}];await nodes.rom.onchange();assert.equal(nodes.status.textContent,'test.nes');const key=(type,code)=>listeners[type].forEach(fn=>fn({type,code,preventDefault(){}}));const read=()=>{c.w(0x4016,1);c.w(0x4016,0);return Array.from({length:8},()=>c.r(0x4016)&1);};for(const[index,code]of ['KeyX','KeyZ','Space','Enter','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].entries()){key('keydown',code);assert.deepEqual(read(),Array.from({length:8},(_,i)=>i===index?1:0),code+' down');key('keyup',code);assert.deepEqual(read(),Array(8).fill(0),code+' up');}key('keydown','KeyX');key('keydown','ArrowRight');assert.deepEqual(read(),[1,0,0,0,0,0,0,1]);for(const fn of listeners.blur)fn();assert.deepEqual(read(),Array(8).fill(0));});
